// Dependency-free Rust harness: discriminate numeric precision models A/B/C
// against the real binary's printed output.
use std::io::{self, Read, Write};

// ---------------- %g precision-6 formatter (mimics std::ostream << float/double) -------------
fn strip_trailing_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        let t = t.trim_end_matches('.');
        t.to_string()
    } else {
        s.to_string()
    }
}

/// Exactly reproduces glibc printf("%g", x) with default precision 6,
/// which is what `std::cout << (float|double)` produces with default stream flags.
fn fmt_g6(x: f64) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if x.is_infinite() {
        return if x < 0.0 { "-inf".into() } else { "inf".into() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    // Style-e rendering at precision P-1 = 5 determines the decimal exponent X.
    let e = format!("{:.*e}", 5usize, x);
    let pos = e.find('e').unwrap();
    let expv: i32 = e[pos + 1..].parse().unwrap();
    if expv < -4 || expv >= 6 {
        let mant = strip_trailing_zeros(&e[..pos]);
        format!("{}e{}{:02}", mant, if expv < 0 { "-" } else { "+" }, expv.abs())
    } else {
        let prec = (5 - expv) as usize;
        strip_trailing_zeros(&format!("{:.*}", prec, x))
    }
}

fn line(v: [f64; 6]) -> String {
    let mut s = String::new();
    for (i, x) in v.iter().enumerate() {
        if i > 0 {
            s.push(' ');
        }
        s.push_str(&fmt_g6(*x));
    }
    s
}

// ---------------- the three candidate numeric models ----------------
// (A) everything f32, f32 constants
fn model_a(r: f32, g: f32, b: f32) -> [f64; 6] {
    let ir = 1.0f32 - r;
    let ig = 1.0f32 - g;
    let ib = 1.0f32 - b;
    let l = 0.2126f32 * r + 0.7152f32 * g + 0.0722f32 * b;
    [ir as f64, ig as f64, ib as f64, l as f64, l as f64, l as f64]
}
// (B) f32 storage, f64 arithmetic with f64 constants, narrowed back to f32 on store
fn model_b(r: f32, g: f32, b: f32) -> [f64; 6] {
    let (rd, gd, bd) = (r as f64, g as f64, b as f64);
    let ir = (1.0f64 - rd) as f32;
    let ig = (1.0f64 - gd) as f32;
    let ib = (1.0f64 - bd) as f32;
    let l = (0.2126f64 * rd + 0.7152f64 * gd + 0.0722f64 * bd) as f32;
    [ir as f64, ig as f64, ib as f64, l as f64, l as f64, l as f64]
}
// (C) parse f32 then widen: all storage and arithmetic in f64
fn model_c(r: f32, g: f32, b: f32) -> [f64; 6] {
    let (rd, gd, bd) = (r as f64, g as f64, b as f64);
    let ir = 1.0f64 - rd;
    let ig = 1.0f64 - gd;
    let ib = 1.0f64 - bd;
    let l = 0.2126f64 * rd + 0.7152f64 * gd + 0.0722f64 * bd;
    [ir, ig, ib, l, l, l]
}

// ---------------- deterministic PRNG (xorshift64*) ----------------
struct Rng(u64);
impl Rng {
    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545F4914F6CDD1D)
    }
    fn next_u32(&mut self) -> u32 {
        (self.next_u64() >> 32) as u32
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next_u64() % n
    }
    fn unit(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }
}

// shortest round-trip decimal for an f32 (strtof parses it back bit-identically)
fn s32(v: f32) -> String {
    format!("{:e}", v)
}

fn ok(v: f32) -> bool {
    v.is_finite()
}

fn emit(out: &mut impl Write, r: &str, g: &str, b: &str, tag: &str) {
    let (rf, gf, bf) = match (r.parse::<f32>(), g.parse::<f32>(), b.parse::<f32>()) {
        (Ok(a), Ok(b2), Ok(c)) => (a, b2, c),
        _ => return,
    };
    if !(ok(rf) && ok(gf) && ok(bf)) {
        return;
    }
    let (a, bm, c) = (model_a(rf, gf, bf), model_b(rf, gf, bf), model_c(rf, gf, bf));
    let (sa, sb, sc) = (line(a), line(bm), line(c));
    if sa == sb && sb == sc {
        return;
    }
    writeln!(out, "{}\t{}\t{}\t{}\t{}\t{}\t{}", tag, r, g, b, sa, sb, sc).unwrap();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode = args.get(1).map(|s| s.as_str()).unwrap_or("search");
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    match mode {
        // print fmt_g6 for each whitespace-separated f64 on stdin, one per line
        "fmt" => {
            let mut s = String::new();
            io::stdin().read_to_string(&mut s).unwrap();
            for tok in s.split_whitespace() {
                let v: f64 = tok.parse().unwrap();
                writeln!(out, "{}", fmt_g6(v)).unwrap();
            }
        }
        // read triples from stdin ("r g b" per line), print all three models
        "eval" => {
            let mut s = String::new();
            io::stdin().read_to_string(&mut s).unwrap();
            for l in s.lines() {
                let p: Vec<&str> = l.split_whitespace().collect();
                if p.len() < 3 {
                    continue;
                }
                let (rf, gf, bf) = (
                    p[0].parse::<f32>().unwrap(),
                    p[1].parse::<f32>().unwrap(),
                    p[2].parse::<f32>().unwrap(),
                );
                writeln!(
                    out,
                    "{}\t{}\t{}\t{}",
                    l.trim(),
                    line(model_a(rf, gf, bf)),
                    line(model_b(rf, gf, bf)),
                    line(model_c(rf, gf, bf))
                )
                .unwrap();
            }
        }
        // emit random f64 values for cross-checking fmt_g6 against bash printf %g
        "fmtgen" => {
            let n: u64 = args.get(2).map(|s| s.parse().unwrap()).unwrap_or(2000);
            let mut rng = Rng(0x1234_5678_9abc_def1);
            for i in 0..n {
                let v: f64 = match i % 6 {
                    0 => f32::from_bits(rng.next_u32()) as f64, // f32-derived
                    1 => f64::from_bits(rng.next_u64()),
                    2 => (rng.below(2_000_000) as f64) / 1000.0,
                    3 => rng.unit() * 10f64.powi((rng.below(41) as i32) - 20),
                    4 => (rng.below(1_000_000_000) as f64) * 1e-3,
                    _ => (rng.below(2_000_001) as f64) - 1_000_000.0,
                };
                if v.is_finite() {
                    writeln!(out, "{:e}", v).unwrap();
                }
            }
        }
        _ => {
            let mut rng = Rng(0xdead_beef_cafe_1234);

            // ---- S1: millions of random f32 bit patterns ----
            for _ in 0..2_000_000u64 {
                let r = f32::from_bits(rng.next_u32());
                let g = f32::from_bits(rng.next_u32());
                let b = f32::from_bits(rng.next_u32());
                if ok(r) && ok(g) && ok(b) {
                    emit(&mut out, &s32(r), &s32(g), &s32(b), "S1rand32");
                }
            }

            // ---- S2: random f32 restricted to one decade at a time (all decades) ----
            for k in -40i32..=38 {
                for _ in 0..40_000u64 {
                    let mk = |rng: &mut Rng| -> f32 {
                        let m = rng.unit() * 10.0;
                        let s = if rng.next_u64() & 1 == 0 { 1.0 } else { -1.0 };
                        (s * m * 10f64.powi(k)) as f32
                    };
                    let (r, g, b) = (mk(&mut rng), mk(&mut rng), mk(&mut rng));
                    if ok(r) && ok(g) && ok(b) {
                        emit(&mut out, &s32(r), &s32(g), &s32(b), &format!("S2dec{}", k));
                    }
                }
            }

            // ---- S3: random full-precision decimal strings, 9..17 significant digits ----
            for _ in 0..600_000u64 {
                let mk = |rng: &mut Rng| -> String {
                    let nd = 9 + rng.below(9) as usize;
                    let mut d = String::new();
                    d.push(char::from(b'1' + rng.below(9) as u8));
                    for _ in 1..nd {
                        d.push(char::from(b'0' + rng.below(10) as u8));
                    }
                    let ex = (rng.below(61) as i32) - 30;
                    let sg = if rng.next_u64() & 1 == 0 { "" } else { "-" };
                    format!("{}{}.{}e{}", sg, &d[..1], &d[1..], ex)
                };
                let (a, b, c) = (mk(&mut rng), mk(&mut rng), mk(&mut rng));
                emit(&mut out, &a, &b, &c, "S3dstr");
            }

            // ---- S4: 7th significant digit parked on a round-half boundary ----
            // build 6 random significant digits, then append "5" + noise, all exponents
            for _ in 0..800_000u64 {
                let mk = |rng: &mut Rng| -> String {
                    let mut d = String::new();
                    d.push(char::from(b'1' + rng.below(9) as u8));
                    for _ in 0..5 {
                        d.push(char::from(b'0' + rng.below(10) as u8));
                    }
                    d.push('5');
                    // trailing noise right after the boundary digit
                    match rng.below(4) {
                        0 => {}
                        1 => d.push_str("0000001"),
                        2 => d.push_str("000000"),
                        _ => d.push_str("9999999"),
                    }
                    let ex = (rng.below(45) as i32) - 22;
                    let sg = if rng.next_u64() & 1 == 0 { "" } else { "-" };
                    format!("{}{}.{}e{}", sg, &d[..1], &d[1..], ex)
                };
                let (a, b, c) = (mk(&mut rng), mk(&mut rng), mk(&mut rng));
                emit(&mut out, &a, &b, &c, "S4half");
            }

            // ---- S5: subnormal / tiny f32 ----
            for _ in 0..400_000u64 {
                let mk = |rng: &mut Rng| -> f32 {
                    let bits = (rng.next_u32() & 0x807f_ffff) | ((rng.below(12) as u32) << 23);
                    f32::from_bits(bits)
                };
                let (r, g, b) = (mk(&mut rng), mk(&mut rng), mk(&mut rng));
                if ok(r) && ok(g) && ok(b) {
                    emit(&mut out, &s32(r), &s32(g), &s32(b), "S5sub");
                }
            }

            // ---- S6: catastrophic cancellation in the luma sum ----
            for k in -30i32..=30 {
                for _ in 0..8_000u64 {
                    let r = (rng.unit() * 9.0 + 1.0) * 10f64.powi(k);
                    let rf = r as f32;
                    let bf = ((rng.unit() * 9.0 + 1.0) * 10f64.powi(k - (rng.below(4) as i32)))
                        as f32;
                    // solve 0.2126*r + 0.7152*g + 0.0722*b = 0 for g, in f64, then round to f32
                    let gexact =
                        -(0.2126f64 * (rf as f64) + 0.0722f64 * (bf as f64)) / 0.7152f64;
                    let mut gf = gexact as f32;
                    // jitter g by a few ulps so the residual sweeps through zero
                    let j = (rng.below(9) as i64) - 4;
                    if gf.is_finite() && gf != 0.0 {
                        let nb = (gf.to_bits() as i64 + j) as u32;
                        gf = f32::from_bits(nb);
                    }
                    if ok(rf) && ok(gf) && ok(bf) {
                        emit(&mut out, &s32(rf), &s32(gf), &s32(bf), &format!("S6canc{}", k));
                    }
                }
            }

            // ---- S7: cancellation in a two-term sum (b=0) plus pure-pair sweeps ----
            for k in -30i32..=30 {
                for _ in 0..8_000u64 {
                    let rf = ((rng.unit() * 9.0 + 1.0) * 10f64.powi(k)) as f32;
                    let gexact = -(0.2126f64 * (rf as f64)) / 0.7152f64;
                    let mut gf = gexact as f32;
                    let j = (rng.below(7) as i64) - 3;
                    if gf.is_finite() && gf != 0.0 {
                        gf = f32::from_bits((gf.to_bits() as i64 + j) as u32);
                    }
                    if ok(rf) && ok(gf) {
                        emit(&mut out, &s32(rf), &s32(gf), "0", &format!("S7canc{}", k));
                    }
                }
            }

            // ---- S8: invert-only stress: c very close to 1, and huge |c| ----
            for _ in 0..600_000u64 {
                let mk = |rng: &mut Rng| -> f32 {
                    match rng.below(3) {
                        0 => {
                            let d = rng.unit() * 10f64.powi(-(rng.below(12) as i32));
                            (1.0f64 + if rng.next_u64() & 1 == 0 { d } else { -d }) as f32
                        }
                        1 => (rng.unit() * 10f64.powi(rng.below(39) as i32)) as f32,
                        _ => f32::from_bits(rng.next_u32() & 0x7fff_ffff),
                    }
                };
                let (r, g, b) = (mk(&mut rng), mk(&mut rng), mk(&mut rng));
                if ok(r) && ok(g) && ok(b) {
                    emit(&mut out, &s32(r), &s32(g), &s32(b), "S8inv");
                }
            }
        }
    }
    out.flush().unwrap();
}

