// Refinement round: (1) isolate invert-only disagreements, (2) test association / FMA variants.
use std::io::{self, Read, Write};

fn stz(s: &str) -> String {
    if s.contains('.') { s.trim_end_matches('0').trim_end_matches('.').to_string() } else { s.to_string() }
}
fn fmt_g6(x: f64) -> String {
    if x.is_nan() { return if x.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if x.is_infinite() { return if x < 0.0 { "-inf".into() } else { "inf".into() }; }
    if x == 0.0 { return if x.is_sign_negative() { "-0".into() } else { "0".into() }; }
    let e = format!("{:.*e}", 5usize, x);
    let p = e.find('e').unwrap();
    let xe: i32 = e[p + 1..].parse().unwrap();
    if xe < -4 || xe >= 6 {
        format!("{}e{}{:02}", stz(&e[..p]), if xe < 0 { "-" } else { "+" }, xe.abs())
    } else {
        stz(&format!("{:.*}", (5 - xe) as usize, x))
    }
}
fn j3(a: f64, b: f64, c: f64) -> String { format!("{} {} {}", fmt_g6(a), fmt_g6(b), fmt_g6(c)) }
fn six(i: [f64; 3], l: f64) -> String { format!("{} {}", j3(i[0], i[1], i[2]), j3(l, l, l)) }

struct Rng(u64);
impl Rng {
    fn n(&mut self) -> u64 { let mut x = self.0; x ^= x >> 12; x ^= x << 25; x ^= x >> 27; self.0 = x; x.wrapping_mul(0x2545F4914F6CDD1D) }
    fn u32v(&mut self) -> u32 { (self.n() >> 32) as u32 }
    fn below(&mut self, n: u64) -> u64 { self.n() % n }
    fn unit(&mut self) -> f64 { (self.n() >> 11) as f64 / (1u64 << 53) as f64 }
}
// only values std::stof accepts without throwing: 0 or FLT_MIN <= |v| <= FLT_MAX (margin applied)
fn safe(v: f32) -> bool {
    v == 0.0 || (v.is_finite() && v.abs() >= f32::MIN_POSITIVE * 1.001 && v.abs() <= f32::MAX * 0.999)
}
fn s32(v: f32) -> String { format!("{:e}", v) }

// ---- invert variants ----
fn inv_f32(r: f32, g: f32, b: f32) -> [f64; 3] { [(1.0f32 - r) as f64, (1.0f32 - g) as f64, (1.0f32 - b) as f64] }
fn inv_f64_narrow(r: f32, g: f32, b: f32) -> [f64; 3] {
    [((1.0f64 - r as f64) as f32) as f64, ((1.0f64 - g as f64) as f32) as f64, ((1.0f64 - b as f64) as f32) as f64]
}
fn inv_f64(r: f32, g: f32, b: f32) -> [f64; 3] { [1.0 - r as f64, 1.0 - g as f64, 1.0 - b as f64] }

// ---- luma variants (all f32 storage unless noted) ----
fn luma_lr(r: f32, g: f32, b: f32) -> f32 { (0.2126f32 * r + 0.7152f32 * g) + 0.0722f32 * b }
fn luma_rl(r: f32, g: f32, b: f32) -> f32 { 0.2126f32 * r + (0.7152f32 * g + 0.0722f32 * b) }
fn luma_fma_all(r: f32, g: f32, b: f32) -> f32 { (0.0722f32).mul_add(b, (0.7152f32).mul_add(g, 0.2126f32 * r)) }
fn luma_fma_last(r: f32, g: f32, b: f32) -> f32 { (0.0722f32).mul_add(b, 0.2126f32 * r + 0.7152f32 * g) }

fn main() {
    let a: Vec<String> = std::env::args().collect();
    let mode = a.get(1).map(|s| s.as_str()).unwrap_or("inv");
    let so = io::stdout();
    let mut o = io::BufWriter::new(so.lock());
    let mut rng = Rng(0x51ed_270b_6996_1234);

    if mode == "inv" {
        // Hunt triples where the INVERT triple alone discriminates f32 vs f64-narrowed vs f64.
        let mut found = 0u64;
        let mut tries = 0u64;
        while found < 400 && tries < 40_000_000 {
            tries += 1;
            let mk = |rng: &mut Rng| -> f32 {
                match rng.below(5) {
                    0 => { let d = rng.unit() * 10f64.powi(-(rng.below(10) as i32)); (1.0 + if rng.n() & 1 == 0 { d } else { -d }) as f32 }
                    1 => (rng.unit() * 10f64.powi((rng.below(20) as i32) - 10)) as f32,
                    2 => (-(rng.unit()) * 10f64.powi((rng.below(20) as i32) - 10)) as f32,
                    3 => (rng.unit() * 10f64.powi(rng.below(30) as i32)) as f32,
                    _ => f32::from_bits(rng.u32v()),
                }
            };
            let (r, g, b) = (mk(&mut rng), mk(&mut rng), mk(&mut rng));
            if !(safe(r) && safe(g) && safe(b)) { continue; }
            let (i1, i2, i3) = (inv_f32(r, g, b), inv_f64_narrow(r, g, b), inv_f64(r, g, b));
            let (s1, s2, s3) = (j3(i1[0], i1[1], i1[2]), j3(i2[0], i2[1], i2[2]), j3(i3[0], i3[1], i3[2]));
            if s1 == s2 && s2 == s3 { continue; }
            // keep the luma part identical across rows so only invert discriminates
            let l = luma_lr(r, g, b) as f64;
            let pat = if s1 == s2 { "INVf32=INVnarrow_vs_INVf64" } else if s2 == s3 { "INVnarrow=INVf64_vs_INVf32" } else if s1 == s3 { "odd" } else { "INVall3differ" };
            writeln!(o, "{}\t{}\t{}\t{}\t{}\t{}\t{}", pat, s32(r), s32(g), s32(b),
                six(i1, l), six(i2, l), six(i3, l)).unwrap();
            found += 1;
        }
        eprintln!("invert witnesses={} tries={}", found, tries);
    } else {
        // Hunt triples where luma summation ORDER or FMA changes the printed value.
        let mut found = 0u64;
        let mut tries = 0u64;
        while found < 400 && tries < 60_000_000 {
            tries += 1;
            // cancellation-heavy: makes association and FMA maximally visible
            let k = (rng.below(50) as i32) - 25;
            let r = ((rng.unit() * 9.0 + 1.0) * 10f64.powi(k)) as f32;
            let b = ((rng.unit() * 9.0 + 1.0) * 10f64.powi(k - (rng.below(3) as i32))) as f32;
            let ge = -(0.2126f64 * (r as f64) + 0.0722f64 * (b as f64)) / 0.7152f64;
            let mut g = ge as f32;
            if g == 0.0 || !g.is_finite() { continue; }
            let jj = (rng.below(11) as i64) - 5;
            g = f32::from_bits((g.to_bits() as i64 + jj) as u32);
            if !(safe(r) && safe(g) && safe(b)) { continue; }
            let (l1, l2, l3, l4) = (luma_lr(r, g, b), luma_rl(r, g, b), luma_fma_all(r, g, b), luma_fma_last(r, g, b));
            let (f1, f2, f3, f4) = (fmt_g6(l1 as f64), fmt_g6(l2 as f64), fmt_g6(l3 as f64), fmt_g6(l4 as f64));
            if f1 == f2 && f2 == f3 && f3 == f4 { continue; }
            let iv = inv_f32(r, g, b);
            writeln!(o, "LR|RL|FMAall|FMAlast\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
                s32(r), s32(g), s32(b),
                six(iv, l1 as f64), six(iv, l2 as f64), six(iv, l3 as f64)).unwrap();
            writeln!(o, "#fma_last_only\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
                s32(r), s32(g), s32(b), six(iv, l4 as f64), six(iv, l4 as f64), six(iv, l4 as f64)).unwrap();
            found += 1;
        }
        eprintln!("order/fma witnesses={} tries={}", found, tries);
    }
    o.flush().unwrap();
    let _ = io::stdin();
}
